class AuthorizationGrantOut(BaseModel):
    id: str
    machine_id: str
    event_id: str
    issued_at: str
    expires_at: str
    status: str


class AuthorizationGrantUseOut(BaseModel):
    grant_id: str
    use_id: str
    consumed_at: str


class AuthorizationGrantRevocationOut(BaseModel):
    grant_id: str
    revoked_at: str
    status: str


@app.post(
    "/machines/{machine_id}/authorization-grants",
    status_code=201,
    response_model=AuthorizationGrantOut,
)
async def create_authorization_grant(machine_id: str, request: Request):
    """Mint a one-time, short-lived grant for one audit-passing allow event.

    The request carries no query string and a JSON object body with exactly
    two fields: ``event_id`` (a non-empty string naming an authorization
    decision event of the path machine) and ``ttl_seconds`` (a non-boolean
    integer from 1 to 300). Validation runs before any machine, event, or
    basis is read:

    - any query parameter (or repeated parameter) is
      ``422 {"error":{"code":"invalid_query"}}``;
    - a missing body, a body that is not a JSON object, a missing or extra
      field, a non-string/empty ``event_id``, or a ``ttl_seconds`` that is
      missing, boolean, fractional, non-integer, or outside 1..300 is
      ``422 {"error":{"code":"invalid_grant_request"}}`` — even against a
      non-existent machine the query check still wins, and every body check
      still precedes the lookups.

    After validation a missing machine, a missing event, or an event owned by
    another machine is ``404 {"error":{"code":"not_found"}}``. An event that is
    not a committed policy allow (``allowed = true`` with
    ``reason = "allowed_by_policy"``) is ``409 event_not_allowed``; an event
    without a historical decision-basis snapshot is
    ``409 decision_basis_unavailable``; one whose snapshot fails the
    read-only consistency audit is ``409 decision_basis_invalid``. Each event
    can be signed at most once: concurrent requests for the same event have
    exactly one ``201`` success and every other one
    ``409 grant_already_exists``, enforced inside one locked write
    transaction backed by a database-level unique constraint. The success
    body is ``{id, machine_id, event_id, issued_at, expires_at, status}`` with
    ``status "active"`` and ``expires_at`` the issue instant plus
    ``ttl_seconds`` as a UTC ``Z`` timestamp. Grant issue never modifies the
    event, its basis, any chain, or any other accountability record.
    """
    # Query validation precedes body parsing and every database read.
    if request.query_params:
        return error_response(422, "invalid_query")

    try:
        payload = await request.json()
    except Exception:
        return error_response(422, "invalid_grant_request")
    if not isinstance(payload, dict) or set(payload) != {
        "event_id",
        "ttl_seconds",
    }:
        return error_response(422, "invalid_grant_request")

    raw_event_id = payload["event_id"]
    ttl_seconds = payload["ttl_seconds"]
    # Booleans are integers in Python and must never be accepted as a TTL;
    # fractional, non-integer, missing-typed (None), and out-of-range values
    # are the same single invalid_grant_request outcome. The event id follows
    # the other path-scoped identifiers: a non-string or blank-after-trim
    # value is an illegal body, not a looked-up object.
    if isinstance(raw_event_id, bool) or not isinstance(raw_event_id, str):
        return error_response(422, "invalid_grant_request")
    event_id = raw_event_id.strip()
    if not event_id:
        return error_response(422, "invalid_grant_request")
    if (
        isinstance(ttl_seconds, bool)
        or not isinstance(ttl_seconds, int)
        or not 1 <= ttl_seconds <= 300
    ):
        return error_response(422, "invalid_grant_request")

    engine = request.app.state.engine
    result = grants.issue_grant(
        engine,
        machine_id=machine_id,
        event_id=event_id,
        ttl_seconds=ttl_seconds,
    )
    status = result["status"]
    if status == "not_found":
        return error_response(404, "not_found")
    if status == "event_not_allowed":
        return error_response(409, "event_not_allowed")
    if status == "decision_basis_unavailable":
        return error_response(409, "decision_basis_unavailable")
    if status == "decision_basis_invalid":
        return error_response(409, "decision_basis_invalid")
    if status == "grant_already_exists":
        return error_response(409, "grant_already_exists")
    return AuthorizationGrantOut(**result["grant"])


@app.post(
    "/machines/{machine_id}/authorization-grants/batch",
    status_code=201,
    response_model=list[AuthorizationGrantOut],
)
async def create_authorization_grants_batch(machine_id: str, request: Request):
    """Mint one one-time grant per item for several audit-passing allow events.

    The request carries no query string and a JSON object body with exactly
    one field: ``items``, a non-empty array whose order is preserved. Every
    element is a JSON object with exactly the two fields of the single-issue
    body — ``event_id`` (a non-empty string naming an authorization decision
    event of the path machine) and ``ttl_seconds`` (a non-boolean integer
    from 1 to 300) — and no two elements may name the same event. Validation
    runs before any machine, event, or basis is read:

    - any query parameter (or repeated parameter) is
      ``422 {"error":{"code":"invalid_query"}}``;
    - a missing body, a body that is not a JSON object, a missing or extra
      top-level field, an ``items`` value that is not a non-empty array, an
      element that is not an object with exactly the two fields, an
      ``event_id`` that is non-string or empty, a ``ttl_seconds`` that is
      boolean, fractional, non-integer, or outside 1..300, or a repeated
      event id is ``422 {"error":{"code":"invalid_grant_request"}}`` — even
      against a non-existent machine the query check still wins, and every
      body check still precedes the lookups.

    After validation every item is checked in input order against exactly
    the single-issue eligibility rules, and the first failing item decides
    the whole batch: a missing machine, a missing event, or an event owned
    by another machine is ``404 {"error":{"code":"not_found"}}``; an event
    that is not a committed policy allow is ``409 event_not_allowed``; an
    event without a historical decision-basis snapshot is
    ``409 decision_basis_unavailable``; one whose snapshot fails the
    read-only consistency audit is ``409 decision_basis_invalid``; an event
    that already has a grant is ``409 grant_already_exists``. A rejected
    batch writes nothing — no partial issue is ever committed — and every
    other record is untouched. Each event can still be signed at most once:
    a concurrent single or batch issue racing for any of these events has
    exactly one ``201`` success and every other request
    ``409 grant_already_exists``, enforced inside one locked write
    transaction backed by the database-level unique constraint. The success
    body is the array of grant objects in input order, each with the
    single-issue shape ``{id, machine_id, event_id, issued_at, expires_at,
    status}`` and ``status "active"``: every grant shares one UTC issue
    moment, and each ``expires_at`` is that moment plus the item's own
    ``ttl_seconds``. Batch issue never modifies the events, their bases,
    any chain, or any other accountability record.
    """
    # Query validation precedes body parsing and every database read.
    if request.query_params:
        return error_response(422, "invalid_query")

    try:
        payload = await request.json()
    except Exception:
        return error_response(422, "invalid_grant_request")
    if not isinstance(payload, dict) or set(payload) != {"items"}:
        return error_response(422, "invalid_grant_request")

    raw_items = payload["items"]
    if not isinstance(raw_items, list) or not raw_items:
        return error_response(422, "invalid_grant_request")

    items: list[tuple[str, int]] = []
    seen_event_ids: set[str] = set()
    for element in raw_items:
        if not isinstance(element, dict) or set(element) != {
            "event_id",
            "ttl_seconds",
        }:
            return error_response(422, "invalid_grant_request")
        raw_event_id = element["event_id"]
        ttl_seconds = element["ttl_seconds"]
        # The element fields follow the single-issue body exactly: booleans
        # are integers in Python and must never be accepted as a TTL, and a
        # non-string or blank-after-trim event id is an illegal body, not a
        # looked-up object. A repeated event id within one batch is the same
        # single invalid_grant_request outcome.
        if isinstance(raw_event_id, bool) or not isinstance(raw_event_id, str):
            return error_response(422, "invalid_grant_request")
        event_id = raw_event_id.strip()
        if not event_id:
            return error_response(422, "invalid_grant_request")
        if (
            isinstance(ttl_seconds, bool)
            or not isinstance(ttl_seconds, int)
            or not 1 <= ttl_seconds <= 300
        ):
            return error_response(422, "invalid_grant_request")
        if event_id in seen_event_ids:
            return error_response(422, "invalid_grant_request")
        seen_event_ids.add(event_id)
        items.append((event_id, ttl_seconds))

    engine = request.app.state.engine
    result = grants.issue_grants_batch(engine, machine_id=machine_id, items=items)
    status = result["status"]
    if status == "not_found":
        return error_response(404, "not_found")
    if status == "event_not_allowed":
        return error_response(409, "event_not_allowed")
    if status == "decision_basis_unavailable":
        return error_response(409, "decision_basis_unavailable")
    if status == "decision_basis_invalid":
        return error_response(409, "decision_basis_invalid")
    if status == "grant_already_exists":
        return error_response(409, "grant_already_exists")
    return [AuthorizationGrantOut(**grant) for grant in result["grants"]]


@app.post(
    "/machines/{machine_id}/authorization-grants/{grant_id}/consume",
    response_model=AuthorizationGrantUseOut,
)
async def consume_authorization_grant(
    machine_id: str, grant_id: str, request: Request
):
    """Atomically consume one unused, unexpired grant exactly once.

    The request accepts only an empty query string and an empty request body:
    any query parameter, a repeated parameter, or any carried body (including
    an empty JSON object) is
    ``422 {"error":{"code":"invalid_query"}}`` validated before the machine or
    grant is read, so the same malformed request against a non-existent
    machine is still 422. After validation a missing machine, a missing grant,
    or a grant owned by another machine is
    ``404 {"error":{"code":"not_found"}}``. Consuming an already-consumed
    grant answers ``409 grant_consumed``, consuming an emergency-revoked
    grant answers ``409 grant_revoked``, and a grant past its ``expires_at``
    answers ``409 grant_expired``; these outcomes keep their precedence and
    do not change when the machine is suspended. Only a still-unconsumed,
    unrevoked, unexpired grant on a suspended machine answers
    ``409 machine_suspended``; none of these writes anything. On success
    the grant flips to ``consumed`` and its single use record is inserted in
    one locked write transaction, so a concurrent consumption burst has
    exactly one ``200`` success carrying ``{grant_id, use_id, consumed_at}``;
    the state change and the use record commit together or leave no trace.
    A revocation racing this consumption has one definite terminal winner.
    The machine status change takes the same write lock, so a suspension that
    commits first turns the consumption into ``machine_suspended`` while a
    consumption that commits first keeps its unique success; after the
    machine returns to active the same still-valid grant consumes normally.
    """
    if request.query_params:
        return error_response(422, "invalid_query")
    content_length = request.headers.get("content-length")
    if (content_length is not None and content_length != "0") or (
        content_length is None and "transfer-encoding" in request.headers
    ):
        return error_response(422, "invalid_query")

    engine = request.app.state.engine
    result = grants.consume_grant(
        engine, machine_id=machine_id, grant_id=grant_id
    )
    status = result["status"]
    if status == "not_found":
        return error_response(404, "not_found")
    if status == "grant_consumed":
        return error_response(409, "grant_consumed")
    if status == "grant_revoked":
        return error_response(409, "grant_revoked")
    if status == "grant_expired":
        return error_response(409, "grant_expired")
    if status == "machine_suspended":
        return error_response(409, "machine_suspended")
    return AuthorizationGrantUseOut(**result["use"])


@app.post(
    "/machines/{machine_id}/authorization-grants/batch-consume",
    response_model=list[AuthorizationGrantUseOut],
)
async def consume_authorization_grants_batch(machine_id: str, request: Request):
    """Atomically consume several unused, unexpired grants, or none.

    The request carries no query string and a JSON object body with exactly
    one field: ``grant_ids``, an array of 1 to 100 distinct, non-empty
    strings naming grants of the path machine, in the order they are to be
    confirmed. Validation runs before any machine or grant is read:

    - any query parameter (or repeated parameter) is
      ``422 {"error":{"code":"invalid_query"}}`` — even against a
      non-existent machine the query check still wins;
    - a missing body, a body that is not a JSON object, a missing or extra
      top-level field, a ``grant_ids`` value that is not an array of 1 to
      100 elements, an element that is not a string or is blank after
      trimming, or a repeated grant id is
      ``422 {"error":{"code":"invalid_grant_request"}}``.

    After validation a missing machine, a missing grant, or a grant owned
    by another machine is ``404 {"error":{"code":"not_found"}}``. Every
    grant is then checked in input order against exactly the
    single-consume rules, and the first failing grant decides the whole
    batch: an already-consumed grant answers ``409 grant_consumed``, an
    emergency-revoked grant answers ``409 grant_revoked``, a grant past its
    ``expires_at`` answers ``409 grant_expired``, and a still-usable grant
    on a suspended machine answers ``409 machine_suspended`` — the terminal
    and derived outcomes keep their precedence even while the machine is
    suspended. A rejected batch writes nothing: no state flip, no use
    record, no lifecycle event, no partial consumption. On success every
    grant flips to ``consumed`` and its single use record is inserted in
    one locked write transaction — the same lock the single consume, the
    revocation, and the machine status change take — so a concurrent
    single consume or another batch racing for any of these grants has
    exactly one winner and the loser rolls back entirely, reporting the
    first raced grant's conflict in its own input order. The success body
    is the array of ``{grant_id, use_id, consumed_at}`` objects in input
    order, one per grant, every ``consumed_at`` the same UTC ``Z`` commit
    moment of the batch.
    """
    # Query validation precedes body parsing and every database read.
    if request.query_params:
        return error_response(422, "invalid_query")

    try:
        payload = await request.json()
    except Exception:
        return error_response(422, "invalid_grant_request")
    if not isinstance(payload, dict) or set(payload) != {"grant_ids"}:
        return error_response(422, "invalid_grant_request")

    raw_grant_ids = payload["grant_ids"]
    if not isinstance(raw_grant_ids, list) or not 1 <= len(raw_grant_ids) <= 100:
        return error_response(422, "invalid_grant_request")

    grant_ids: list[str] = []
    seen_grant_ids: set[str] = set()
    for element in raw_grant_ids:
        # The elements follow the other path-scoped identifiers: a
        # non-string or blank-after-trim value is an illegal body, not a
        # looked-up object, and a repeated id within one batch is the same
        # single invalid_grant_request outcome.
        if isinstance(element, bool) or not isinstance(element, str):
            return error_response(422, "invalid_grant_request")
        grant_id = element.strip()
        if not grant_id:
            return error_response(422, "invalid_grant_request")
        if grant_id in seen_grant_ids:
            return error_response(422, "invalid_grant_request")
        seen_grant_ids.add(grant_id)
        grant_ids.append(grant_id)

    engine = request.app.state.engine
    result = grants.consume_grants_batch(
        engine, machine_id=machine_id, grant_ids=grant_ids
    )
    status = result["status"]
    if status == "not_found":
        return error_response(404, "not_found")
    if status == "grant_consumed":
        return error_response(409, "grant_consumed")
    if status == "grant_revoked":
        return error_response(409, "grant_revoked")
    if status == "grant_expired":
        return error_response(409, "grant_expired")
    if status == "machine_suspended":
        return error_response(409, "machine_suspended")
    return [AuthorizationGrantUseOut(**use) for use in result["uses"]]


@app.post(
    "/machines/{machine_id}/authorization-grants/{grant_id}/revoke",
    response_model=AuthorizationGrantRevocationOut,
)
async def revoke_authorization_grant(
    machine_id: str, grant_id: str, request: Request
):
    """Emergency-revoke one unconsumed, unrevoked, unexpired grant.

    The request accepts only an empty query string and an empty request body:
    any query parameter, a repeated parameter, or any carried body (including
    an empty JSON object) is
    ``422 {"error":{"code":"invalid_query"}}`` validated before the machine or
    grant is read, so the same malformed request against a non-existent
    machine is still 422. After validation a missing machine, a missing grant,
    or a grant owned by another machine is
    ``404 {"error":{"code":"not_found"}}``. Revoking an already-consumed grant
    answers ``409 grant_consumed``, revoking an already-revoked grant answers
    ``409 grant_revoked``, and revoking a grant past its ``expires_at``
    answers ``409 grant_expired``; none of these writes anything. On success
    the grant flips to ``revoked`` and ``revoked_at`` is stamped in one locked
    write transaction — the same lock the consume operation takes — so a
    concurrent revocation burst has exactly one ``200`` success and a
    revocation racing a consumption has one definite terminal winner: consume
    first makes this call answer ``grant_consumed``; revoke first makes the
    consumption answer ``grant_revoked``. The success body is
    ``{grant_id, revoked_at, status}`` with ``status "revoked"`` and
    ``revoked_at`` a UTC ``Z`` RFC 3339 instant. Revocation changes only the
    grant's own status and stamp: it never modifies the decision event, the
    immutable decision basis, any hash chain, evidence, incident, diagnostic,
    or export, and adds no renewal, transfer, or deletion entry.
    """
    if request.query_params:
        return error_response(422, "invalid_query")
    content_length = request.headers.get("content-length")
    if (content_length is not None and content_length != "0") or (
        content_length is None and "transfer-encoding" in request.headers
    ):
        return error_response(422, "invalid_query")

    engine = request.app.state.engine
    result = grants.revoke_grant(
        engine, machine_id=machine_id, grant_id=grant_id
    )
    status = result["status"]
    if status == "not_found":
        return error_response(404, "not_found")
    if status == "grant_consumed":
        return error_response(409, "grant_consumed")
    if status == "grant_revoked":
        return error_response(409, "grant_revoked")
    if status == "grant_expired":
        return error_response(409, "grant_expired")
    return AuthorizationGrantRevocationOut(**result["revocation"])


# --- read-only authorization grant audit listing ------------------------------


_GRANT_LIST_DEFAULT_LIMIT = 50
_GRANT_LIST_FAR_FUTURE = datetime.max.replace(tzinfo=timezone.utc)


class AuthorizationGrantListParams(BaseModel):
    limit: int
    cursor: str | None = None


def validate_authorization_grant_list_params(
    request: Request,
) -> AuthorizationGrantListParams:
    """Validate the grant audit-list query before any machine or grant read.

    Exactly two parameters are accepted: the optional ``limit`` and the
    optional opaque ``cursor``; no other parameter names and no request body.
    Every malformed request — a carried body, an unknown parameter name, a
    repeated ``limit`` or ``cursor``, a ``limit`` that is missing-shaped,
    fractional, boolean, non-decimal, or outside 1..100, or a ``cursor`` that
    is empty or does not have the issued-cursor shape — is the single 422
    ``invalid_query`` outcome, raised here before the machine or any grant is
    read. ``limit`` omitted defaults to 50; ``cursor`` omitted starts the
    listing at the beginning.
    """
    # A body on a GET is an unknown-shape request, rejected in the validation
    # phase before any machine or grant is read. A present non-zero
    # Content-Length, or a chunked request without one, means a body is being
    # carried.
    content_length = request.headers.get("content-length")
    if (content_length is not None and content_length != "0") or (
        content_length is None and "transfer-encoding" in request.headers
    ):
        raise QueryError("invalid_query")

    allowed = {"limit", "cursor"}
    unknown = [name for name in request.query_params if name not in allowed]
    if unknown:
        raise QueryError("invalid_query")

    # A repeated parameter name is itself an unknown-shape query: reject
    # ``limit=1&limit=2`` (and a repeated ``cursor``) rather than silently
    # taking one occurrence.
    if len(request.query_params.getlist("limit")) > 1:
        raise QueryError("invalid_query")
    if len(request.query_params.getlist("cursor")) > 1:
        raise QueryError("invalid_query")

    raw_limit = request.query_params.get("limit")
    if raw_limit is None:
        limit = _GRANT_LIST_DEFAULT_LIMIT
    else:
        # Query parameters arrive as strings, so every value is text here; a
        # boolean (``true``), fractional (``1.0``), blank, or otherwise
        # non-decimal value never matches the integer shape. ``-?\d+`` also
        # rejects surrounding whitespace and signs other than ``-``.
        if not _INTEGER_QUERY_RE.fullmatch(raw_limit):
            raise QueryError("invalid_query")
        limit = int(raw_limit)
        if not 1 <= limit <= 100:
            raise QueryError("invalid_query")

    cursor = request.query_params.get("cursor")
    if cursor is not None:
        # Opaque issued cursor: ``<issued_at RFC 3339 Z text>|<grant id>``.
        # Issued stamps never contain ``|``, so exactly one separator is
        # required; the stamp segment must be shaped like a stored UTC Z
        # instant and the id segment must be non-empty. Resolving the pair
        # against the path machine's stored grants happens in the handler.
        parts = cursor.split("|")
        if (
            len(parts) != 2
            or not _RFC3339_Z_DATETIME_RE.fullmatch(parts[0])
            or not parts[1]
        ):
            raise QueryError("invalid_query")

    return AuthorizationGrantListParams(limit=limit, cursor=cursor)


def _grant_issued_instant(value: object) -> datetime:
    """Parse a stored grant ``issued_at`` to its actual UTC instant.

    Legitimately written values always satisfy the RFC 3339 ``Z`` contract; a
    damaged value sorts after every parseable record instead of crashing the
    read-only audit listing, and its stored text is still emitted verbatim.
    """
    if isinstance(value, str) and _RFC3339_Z_DATETIME_RE.fullmatch(value):
        try:
            return parse_utc_z_datetime(value)
        except ValueError:
            pass
    return _GRANT_LIST_FAR_FUTURE


def _grant_expires_instant(value: object) -> datetime:
    """Parse a stored grant ``expires_at`` tolerantly for derived expiry.

    A value that no longer parses cannot be shown as expired (the expiry
    instant is unknowable from the stored text), so it sorts as a far-future
    instant and the non-terminal grant presents ``active``; the read-only
    listing never crashes, rewrites, or repairs the stored stamp.
    """
    if isinstance(value, str) and _RFC3339_Z_DATETIME_RE.fullmatch(value):
        try:
            return parse_utc_z_datetime(value)
        except ValueError:
            pass
    return _GRANT_LIST_FAR_FUTURE


def _grant_id_key(value: object) -> tuple[int, str]:
    """Tie-break key for a stored grant id, tolerant of a damaged value."""
    if isinstance(value, str):
        return (0, value)
    return (1, "")


def authorization_grant_to_dict(
    record: AuthorizationGrant,
    use_by_grant: dict[str, AuthorizationGrantUse],
    *,
    now: datetime,
) -> dict[str, object]:
    """One stored grant as the fixed ten-field audit-list view.

    The four lifecycle stamps (``issued_at``, ``expires_at``,
    ``consumed_at``, ``revoked_at``) and the identifiers are emitted exactly
    as stored; nothing is normalized or rewritten. ``status`` is derived at
    read time: the terminal states ``consumed`` and ``revoked`` are kept from
    storage even after the TTL elapses, and a non-terminal grant presents
    ``expired`` once the current UTC instant reaches ``expires_at`` and
    ``active`` before it — the derived status is never persisted. ``use_id``
    and ``use_at`` carry the grant's unique consumption record, and are
    ``null`` together when the grant was never consumed.
    """
    if record.status == "consumed" or record.status == "revoked":
        # Terminal states are permanent: expiry never downgrades or rewrites
        # them, and the listing mirrors stored state without a write-back.
        status = record.status
    elif now >= _grant_expires_instant(record.expires_at):
        status = "expired"
    else:
        status = "active"

    use = use_by_grant.get(record.id)
    return {
        "id": record.id,
        "machine_id": record.machine_id,
        "event_id": record.event_id,
        "issued_at": record.issued_at,
        "expires_at": record.expires_at,
        "status": status,
        "consumed_at": record.consumed_at,
        "revoked_at": record.revoked_at,
        "use_id": use.id if use is not None else None,
        "use_at": use.consumed_at if use is not None else None,
    }


@app.get("/machines/{machine_id}/authorization-grants")
def list_authorization_grants(
    machine_id: str,
    params: Annotated[
        AuthorizationGrantListParams,
        Depends(validate_authorization_grant_list_params),
    ],
    session: SessionDep,
):
    """Read-only keyset-paginated audit listing of one machine's grants.

    Only ``GET`` is routed, so non-GET methods (including ``HEAD``) return
    ``405`` without reading grants, computing a page, or writing anything.
    The caller submits only the path machine id, an optional ``limit`` (a
    non-boolean integer from 1 to 100, defaulting to 50 when omitted), and an
    optional opaque ``cursor`` returned by a previous page — no other
    parameter names and no request body. A carried body, an unknown or
    repeated parameter, a non-integer or out-of-range ``limit``, or a
    malformed ``cursor`` is ``422 {"error":{"code":"invalid_query"}}`` raised
